class ScoutApi(object):
    def __init__(self, scout_testline_name, api_key, base_url, api_version, config, ute_test_case_id, timeout):
        """
        Initialize ScoutApi class.
        :param string scout_testline_name: Testline name registered in Scout, i.e. 'MRBTS-101048'
        :param string api_key: Scout API Key. This is optional parameter as api_key is no longer required by most of
        keywords. If keyword requires api_key an appriopriate annotation is added to its docstring. You can request
        Your API key by email at contact provided at the top of this documentation.
        :param string base_url: URL to scout instance, i.e.: https://scout.wro.nsn-rdnet.net.
        :param string api_version: version of scout api, i.e. 'v1'.
        :param int timeout: timeout to scout connection requests, i.e. 240
        """
        self.api_key = api_key
        self.config = config
        self.base_url = base_url
        self.api_version = api_version
        self.scout_testline_id = None
        self.scout_testline_name = scout_testline_name
        self.ute_test_case_id = ute_test_case_id
        self.timeout = timeout
        self.connection = ScoutApiConnection(base_url, api_version, api_key, timeout)

    def setup(self):

        """Checks connection to Scout with parameters provided to class instance. If connection not possible,
        testline does not exists - exception will be raised.

        :return None.
        """
        version = importlib_metadata.version('taf.sw.scout') if importlib_metadata \
            else get_distribution('taf.sw.scout').version
        header_version = ' '.join([10 * "-", 'taf.sw.scout {} version'.format(version), 10 * "-"])
        logger.info(header_version)
        params = {
            'fields[testline]': 'id'
        }
        try:
            data = self._get_testline_data(params)
        except GetRequestException as e:
            if e.args[1]['status_code'] == 404:
                raise ConnectionException(
                    'Testline with scout name "{}" does not exists!'.format(self.scout_testline_name))
            else:
                raise e

        assert 'id' in data, 'ID of testline is missing'
        self.scout_testline_id = data['id']

