    def get_cell_states(self, cell_id):
        """Get states of selected cell.

        :param string cell_id: infomodel identifier of cell.
        :return dict: states of cells.

        Example:
          api.get_cell_status('LNCEL-R-1')
          ->
          {
            u'administrative_state': u'Unlocked',
            u'operational_state': u'Enabled',
            u'procedural_state': u'OnAirDone'
          }
        """
        data = self._get_testline_parameter('cells')
        if data:
            statuses = self.config['statuses']['cell']
            return {k: v for k, v in data[cell_id].items() if k in statuses}
        return {}

