    def request_scf(self, wait_for_success=True, timeout=600, admin_connect_timeout=60, use_scout_internal_id=False):
        """Sends request to Scout to fetch new SCF and (by default) waits for success for {timeout} seconds. Returns
        Scout SCF id


        - if you use UTE CM to schedule your tests (or you use single run) collected SCF file will be analyzed in Scout
            and the analysis will be send to Reporting Portal where will be matched with your execution. This data will
            be also used for TOP 50 Customer configurations (https://confluence.ext.net.nokia.com/x/6xKGSQ). In this
            scenario you have to leave use_scout_internal_id set to False. In case you ran the robot test manually from
            reserved UTE VM it will be not send to Reporting Portal, it's supported only for tests scheduled by UTE CM
            or single runs!

            (additional info: Execution through UTE CM ensures relation between SCF and UTE Test Execution by
            automatically assigned ute:id for each test execution. taf.sw.scout library retrieves this id on its own and
            reports SCF with it)

        - if you run your test in different way than described above (manually/from command line on VM or you want to
            report even outside robot tests you have to set parameter: use_scout_internal_id=True and
            include returned Scout SCF id in report send to Reporting Portal. If you will perform all required actions
            analysis will be send to Reporting Portal and matched with your reported execution in the same way as above.
            This setting is not recommended for UTE users, but is the only option for tests reported by other automated
            environments like jenkins, etc.

            (additional info: In order to report your Test execution please pass following dict:
            {'test_cases':[{'tc_execution_id':'scf_id_returned_by_request_scf_keyword'}]} to test reporting keyword.
            Reporting Scout SCF id to Reporting Portal is not the part of this keyword, included details could be
            changed and be outdated. In case of any questions how to prepare report please contact Reporting Portal
            team.)


        :param bool wait_for_success: determines if keyword waits for successful SCF retrieval or sends request
            and continue despite the result. It's recommended to leave this option default or SCF download could be
            interrupted by next steps inside your test procedure
        :param int timeout: time (in seconds) keyword waits for successful SCF retrieval
        :param int admin_connect_timeout: time (in seconds) keyword checks admin infomodel connection every 5 seconds
            until timeout is reached
        :param bool use_scout_internal_id: defines whether to report SCF Analysis with Scout SCF id. If so please
            report this test execution with Scout SCF Id you will receive in return of this keyword
        """
        data = {'data': {
            'type': 'scf',
            'attributes': {
                'use_scout_internal_id': use_scout_internal_id,
                'testline': {
                    'id': self.scout_testline_id
                }
            }
        }}
        data = self._check_ute_test_case_id(data, use_scout_internal_id)

        sleep_time = self.config["consts"]["fetch_scf"]["sleep_time"]

        scf_id = self._retry_till_timeout(self._get_scf_id, admin_connect_timeout, sleep_time, [PostRequestException],
                                          "Couldn't get SCF id.\nAdmin infomodel is not running.", data)

        if not scf_id:
            raise EmptySCFIDException("API returned empty SCF id")

        if wait_for_success:
            self._retry_till_timeout(self._check_scf_status, timeout, sleep_time, [GetRequestException],
                                     "Successful SCF retrieval not reached.", scf_id)

        return scf_id

    def _get_scf_id(self, data):
        """
        Fetch SCF id.

        {'data': {
            'type': 'scf',
            'attributes': {
                'use_scout_internal_id': {bool},
                'testline': {
                    'id': {id}
                }
            }
        }}

        :param dict data: data to send during request
        """
        logger.info("Getting SCF id")
        request_endpoint = self.config["endpoints"]["fetch_scf"]
        scf_id = self.connection.post(endpoint=request_endpoint, data=data)[0].get("id", None)
        logger.info("SCF id: {}".format(scf_id if scf_id else "Error"))
        return scf_id

    def _check_scf_status(self, scf_id):
        """
        Check if SCF is fetched successfully.
        Raise a GetRequestException when not ready.

        :param string scf_id: id of SCF to check
        """
        logger.info("Checking SCF fetching status.")
        check_status_endpoint = self.config["endpoints"]["scf"].format(scf_id)
        data = self.connection.get(check_status_endpoint)
        if data[0].get("status") != 230:
            raise GetRequestException("Response status is not successful")

    def _check_comparator_generation_status(self, report_id):
        """
        Check the comparator generation status
        Raise a GetRequestException when report generation is not triggered, triggered.

        :param string report_id: id of the report
        """
        response = self.connection.get(self.config['endpoints']['aggregated_comparator_reports'].format(report_id))
        status = response[0].get('status')
        if status in (300, 310):  # not_triggered, triggered
            raise GetRequestException("Response status is not successful")

        return response

    def _retry_till_timeout(self, function, timeout, sleep_time, allowed_exceptions, message, *args, **kwargs):
        """
        Repeat function until timeout is reached.
        Raise a TimeoutException if timeout has expired, otherwise return the function result.

        :param Callable function: function to execute
        :param int timeout: time to retry executions
        :param int sleep_time: time to wait between execution attempts
        :param list[Exception] allowed_exceptions: exceptions that are allowed to be raised during retries
        :param string message: message to print when allowed exception is raised during retries
        :param args/kwargs: arguments for function
        """
        current_time = time.time()
        end_time = current_time + timeout
        while current_time < end_time:
            logger.info("Time left: {}s".format(int(end_time - current_time)))
            try:
                return function(*args, **kwargs)
            except Exception as exception:
                if exception.__class__ not in allowed_exceptions:
                    raise exception
                logger.debug(exception)
                logger.info(message)
                time.sleep(sleep_time)
                current_time = time.time()
        raise TimeoutException("Timeout reached: {}\n{}".format(timeout, message))

    def _check_ute_test_case_id(self, data, use_scout_internal_id):
        if not self.ute_test_case_id:
            logging.debug("'ute_test_case_id' not set. Trying to get if from test TAGs")
            self.ute_test_case_id = get_execution_id()

        self.log_status_of_ids(use_scout_internal_id, self.ute_test_case_id)
        ute_test_case_id_skipped = self.ute_test_case_id_skipped(use_scout_internal_id, self.ute_test_case_id)

        if ute_test_case_id_skipped:
            self.ute_test_case_id = None

        if self.ute_test_case_id:
            data['data']['attributes']['ute_test_case_id'] = self.ute_test_case_id
        data = json.dumps(data)
        return data

    def _get_testline_parameter(self, parameter):
        """Gets value of selected testline parameter from infomodel. Infomodel path is read from library config.

        :param string parameter: parameter to check.
        :return string: parameter value

        Example:
          api._get_testline_parameter('passive_sw')
          ->
          'SBTS00_130220_1222314'
        """
        data = self._get_testline_data()
        if data:
            param_value = Helper.get_value_from_dict(data,
                                                     self.config['data_pointers']['testline_parameters'][parameter])
            return param_value

    def _get_testline_data(self, params=None):
        """
        Gets testline data from api.
        :param dict params: params to pass in GET request.
        :return dict: testline data

        Example:
          api._get_testline_data(params={'fields[testline]': 'id'})
          ->
          {
            u'meta': {
              u'status_display': 'on air'},
            u'type': u'testline',
            u'id': u'MRBTS-100769'
          }
        """
        endpoint = self.config['endpoints']['testline'].format(self.scout_testline_name)
        return self.connection.get(endpoint, params)[0]

